import React, { useState } from "react";
// This import statement will now resolve correctly!
import CounterClass from "./CounterClass"; 

function ButtonClick({ user, variant }) {
  const [clicks, setClicks] = useState(0);

  const handleClick = () => {
    setClicks(clicks + 1);
  };

  return (
    <div style={{ border: "1px solid #ddd", padding: "15px", margin: "10px", borderRadius: "8px" }}>
      <h3>User: {user}</h3>
      <p>Functional clicks: {clicks}</p>
      <button onClick={handleClick}>Click Me!</button>

      {/* Rendering the newly created class component inside the functional one */}
      <CounterClass />
    </div>
  );
}

export default ButtonClick;
